		const restore = new Promise((resolve) => { resolveRestore = resolve; });
		bridge.callServerTool.mockImplementation(async ({ name }) =>
			name === "restore_lobu_app_result" ? restore : { isError: false },
		);
		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data } = useMcpApp<{ title: string }>();
			return <span>{data?.title ?? "No result"}</span>;
		}
		render(<Provider devMock={{ title: "Development result" }}><Probe /></Provider>);
		await waitFor(() => expect(bridge.callServerTool).toHaveBeenCalledWith({
			name: "restore_lobu_app_result",
			arguments: { snapshot_capability: "compat-cap" },
		}));
